    F14 = F2 + F3;                                      // s1 = g * hp + bp
    F2 = F9 * F3;                                       // g * bp
    F0 = F2 + F15;                                      // lp = g * bp + s2
    F15 = F2 + F0;                                      // s2 = g * bp + lp
    DM(I0, M6) = R0;                                    // temp[n] = lp
    R1 = DM(I1, M5);                                    // aux[n] += temp[n]
    F1 = F1 + F0;
    DM(I1, M6) = R1;
    R1 = 1;
    .NOCOMPRESS;
    R12 = R12 - R1;
    .COMPRESS;
    IF NE JUMP _ste_n;
_ste_z:
    R12 = DM(1, I6);                                    // size - noise_samples zeros
    R1 = DM(2, I6);
    .NOCOMPRESS;
    R12 = R12 - R1;
    .COMPRESS;
    R0 = 0;
    COMP(R12, R0);
    IF LE JUMP _ste_done;
_ste_zl:
    R0 = 0;
    F1 = F10 * F14;                                     // hp = (x - r * s1 - g * s1 - s2) * h
    F1 = F0 - F1;
    F2 = F9 * F14;
    F1 = F1 - F2;
    F1 = F1 - F15;
    F1 = F1 * F11;
    F2 = F9 * F1;                                       // g * hp
    F3 = F2 + F14;                                      // bp = g * hp + s1
    F14 = F2 + F3;                                      // s1 = g * hp + bp
    F2 = F9 * F3;                                       // g * bp
    F0 = F2 + F15;                                      // lp = g * bp + s2
    F15 = F2 + F0;                                      // s2 = g * bp + lp
    DM(I0, M6) = R0;                                    // temp[n] = lp
    R1 = DM(I1, M5);                                    // aux[n] += temp[n]
    F1 = F1 + F0;
    DM(I1, M6) = R1;
    R1 = 1;
    .NOCOMPRESS;
    R12 = R12 - R1;
    .COMPRESS;
    IF NE JUMP _ste_zl;
_ste_done:
    DM(I2, M5) = R13;                                   // rng
    R0 = DM(8, I7);
    I2 = R0;
    R0 = 0;                                             // (DAG gap)
    R1 = 0;
    R2 = 0;
    DM(3, I2) = R14;                                    // state_1
    DM(4, I2) = R15;                                    // state_2
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,8)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I4 = DM(6, I7);
    I2 = DM(7, I7);
    I1 = DM(8, I7);
    I0 = DM(9, I7);
    .NOCOMPRESS;
    I12 = DM(M7, I6);
    .COMPRESS;
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
